// Obtener datos del webhook original
const webhookData = $('Webhook Evolution API').first().json;
const messageType = webhookData.body.data.messageType;

let userMessage = '';
const rawPhone = webhookData.body.data.key.remoteJid;

// ─── NORMALIZACION DE TELEFONO (ajustar al pais de tu negocio) ────────────
function normalizePhone(raw) {
  let clean = raw
    .replace(/@s\.whatsapp\.net|@c\.us/gi, '')
    .replace(/[+\s\-\(\)]/g, '')
    .replace(/\D/g, '');

  if (!clean) return { phone: raw, normalizeError: 'vacio despues de limpiar' };

  let normalized = clean;
  let isLocalCountry = false;
  const COUNTRY_CODE = '{{COUNTRY_CODE}}'; // ej: '54' para Argentina, '52' para Mexico

  if (clean.startsWith(COUNTRY_CODE + '9') && clean.length === 13) {
    normalized = clean;
    isLocalCountry = true;
  } else if (clean.startsWith(COUNTRY_CODE) && clean.length === 12) {
    normalized = COUNTRY_CODE + '9' + clean.slice(2);
    isLocalCountry = true;
  } else if (clean.startsWith('0') && clean.length === 11) {
    normalized = COUNTRY_CODE + '9' + clean.slice(1);
    isLocalCountry = true;
  } else if (clean.length === 10 && !clean.startsWith(COUNTRY_CODE)) {
    normalized = COUNTRY_CODE + '9' + clean;
    isLocalCountry = true;
  } else {
    normalized = clean;
    isLocalCountry = false;
  }

  if (isLocalCountry && normalized.length !== 13) {
    return { phone: clean, normalizeError: `longitud invalida post-normalizacion: ${normalized.length} digitos (raw: ${raw})` };
  }

  return { phone: normalized, normalizeError: null };
}

const { phone: phoneNormalized, normalizeError } = normalizePhone(rawPhone);

if (messageType === 'conversation') {
  userMessage = webhookData.body.data.message.conversation;
} else if (messageType === 'extendedTextMessage') {
  userMessage = webhookData.body.data.message.extendedTextMessage.text;
} else if (messageType === 'audioMessage') {
  try {
    const transcription = $('Transcribir con Whisper').first();
    userMessage = transcription.json.text || '[Audio no transcrito]';
  } catch (e) {
    userMessage = '[Error al transcribir audio]';
  }
}

// Generar calendario de referencia de los proximos 30 dias (evita que el LLM calcule fechas mentalmente)
const diasSemana = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];

const now = new Date();
const tz = new Date(now.getTime() - {{UTC_OFFSET_HOURS}} * 60 * 60 * 1000); // ajustar offset de tu zona horaria
const hoy = new Date(tz.getUTCFullYear(), tz.getUTCMonth(), tz.getUTCDate());

const hoyDia = diasSemana[hoy.getDay()];
const hoyDD = String(hoy.getDate()).padStart(2, '0');
const hoyMM = String(hoy.getMonth() + 1).padStart(2, '0');
const hoyStr = `${hoyDD}/${hoyMM}/${hoy.getFullYear()} = ${hoyDia}`;

let calendarioDias = '';
for (let i = 0; i <= 30; i++) {
  const d = new Date(hoy);
  d.setDate(hoy.getDate() + i);
  const dia = diasSemana[d.getDay()];
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const yyyy = d.getFullYear();
  calendarioDias += `${dd}/${mm}/${yyyy} = ${dia}\n`;
}

return [{
  json: {
    chatInput: userMessage,
    sessionId: phoneNormalized,
    phoneNormalized: phoneNormalized,
    normalizeError: normalizeError,
    pushName: webhookData.body.data.pushName || 'Usuario',
    instanceName: webhookData.body.instance,
    messageType: messageType,
    timestamp: new Date().toISOString(),
    calendarioDias: calendarioDias,
    hoyStr: hoyStr
  }
}];
